      "title": "Ihre Termine, Woche für Woche",
      "sub": "Was bei jedem Termin passiert und was Sie entscheiden",
      "lead": "Das ist der übliche Ablauf in den USA. Ihrer kann anders sein: Ihre Hausärztin, Frauenärztin oder Hebamme fügt Termine und Untersuchungen hinzu, wenn Sie sie brauchen.",
      "afterBirth": "Nach der Geburt",
      "yourChoice": "Ihre Entscheidung",
      "first": {
        "when": "Etwa 8.–10. Woche",
        "title": "Erster Termin",
        "i1": "Ihr Geburtstermin wird nach Ihrer letzten Periode berechnet, oft zusammen mit einem frühen Ultraschall.",
        "i2": "Bluttests: Blutgruppe und Rh, Blutbild, Immunität gegen Röteln und Windpocken, Hepatitis B und C, HIV und Syphilis. Ein Urintest sowie Tests auf Chlamydien und Gonorrhö.",
        "i3": "Ein früher Zuckertest, wenn Sie in einer früheren Schwangerschaft Diabetes hatten oder andere Risikofaktoren haben.",
        "i4": "Wenn Ihr Risiko für Präeklampsie höher ist, senkt niedrig dosiertes Aspirin (81 mg am Tag) ab der 12. Woche dieses Risiko. Fragen Sie, ob es für Sie passt."
      },
      "genetic": {
        "when": "Ab der 10. Woche",
        "title": "Tests für das Baby",
        "i1": "Ein Bluttest ab der 10. Woche (zellfreie DNA) sucht nach Down-Syndrom und einigen anderen Erkrankungen. Ein Suchtest ist keine Diagnose: Ein positives Ergebnis heißt, dass Ihnen ein diagnostischer Test angeboten wird.",
        "i2": "Ein Trägertest prüft, ob Sie Gene für Erkrankungen wie Mukoviszidose oder spinale Muskelatrophie tragen.",
        "i3": "Sie können alle, einige oder keinen dieser Tests machen."
      },
      "monthly": {
        "when": "Alle 4 Wochen, bis zur 28. Woche",
        "title": "Regelmäßige Termine",
        "i1": "Blutdruck, Gewicht, Urin und der Herzschlag des Babys. Ab etwa der 20. Woche wird auch Ihr Bauch gemessen."
      },
      "anatomy": {
        "when": "18.–22. Woche",
        "title": "Organ-Ultraschall",
        "i1": "Ein genauer Ultraschall von Körper und Wachstum des Babys und der Plazenta. Meist können Sie das Geschlecht erfahren, wenn Sie möchten."
      },
      "sugar": {
        "when": "24.–28. Woche",
        "title": "Zuckertest und Blutwerte",
        "i1": "Ein süßes Getränk und eine Stunde später ein Bluttest, um Schwangerschaftsdiabetes zu erkennen.",
        "i2": "Ein Blutbild auf Blutarmut und ein weiterer Syphilis-Test.",
        "i3": "Wenn Ihre Blutgruppe Rh-negativ ist: eine Rh-Spritze (RhoGAM) um die 28. Woche."
      },
      "tdap": {
        "when": "27.–36. Woche",
        "title": "Keuchhusten-Impfung (Tdap)",
        "i1": "Ihre Antikörper gehen auf das Baby über und schützen es in den ersten Monaten, bevor es selbst geimpft werden kann. Sie bekommen sie in jeder Schwangerschaft."
      },
      "twoweekly": {
        "when": "Alle 2 Wochen, ab der 28. Woche",
        "title": "Die Termine werden häufiger",
        "i1": "Lernen Sie, wie sich Ihr Baby normalerweise bewegt. Tritte zu zählen ist freiwillig. Wenn sich das Baby weniger bewegt als sonst, rufen Sie noch am selben Tag an. Warten Sie nicht bis zum nächsten Termin.",
        "i2": "Wenn Sie zum Beispiel Bluthochdruck oder Diabetes haben, beginnen zusätzliche Kontrollen des Babys (CTG oder Ultraschall) oft um die 32. Woche."
      },
      "rsv": {
        "when": "32.–36. Woche, September bis Januar",
        "title": "RSV-Schutz für das Baby",
        "i1": "Entweder eine RSV-Impfung für Sie in der 32. bis 36. Woche oder eine Antikörper-Spritze für das Baby nach der Geburt. Das eine oder das andere, nicht beides. Beides senkt die Wahrscheinlichkeit, dass das Baby im ersten Winter mit RSV ins Krankenhaus muss."
      },
      "gbs": {
        "when": "36.–37. Woche",
        "title": "Abstrich auf Streptokokken der Gruppe B, und die Lage des Babys",
        "i1": "Ein Abstrich von Scheide und Enddarm. Etwa 1 von 4 Frauen trägt GBS, und es schadet Ihnen nicht. Ist Ihr Test positiv, bekommen Sie während der Geburt Antibiotika über die Vene, um das Baby zu schützen.",
        "i2": "Es wird geprüft, ob das Baby mit dem Kopf nach unten liegt. Liegt es mit dem Po nach unten (Beckenendlage), kann man Ihnen anbieten, das Baby zu drehen (äußere Wendung), oder Sie können einen Kaiserschnitt planen.",
        "i3": "Gehen Sie Ihren Geburtsplan durch: Schmerzlinderung, wer bei Ihnen ist, Füttern."
      },
      "weekly": {
        "when": "Jede Woche, ab der 36. Woche",
        "title": "Die letzten Wochen",
        "i1": "Ab der 38. Woche kann man Ihnen eine Eipollösung anbieten: Mit dem Finger wird am Muttermund entlanggestrichen, was helfen kann, die Geburt in Gang zu bringen.",
        "i2": "Eine Einleitung kann ab der 39. Woche angeboten werden. Ab der 41. Woche wird sie empfohlen, weil das Risiko für das Baby zu steigen beginnt."
      },
      "ppBp": {
        "when": "3–10 Tage nach der Geburt",
        "title": "Blutdruckkontrolle, wenn er hoch war",
        "i1": "Wenn Sie Bluthochdruck oder Präeklampsie hatten, lassen Sie den Blutdruck 3 bis 10 Tage nach der Geburt kontrollieren. Präeklampsie kann nach der Geburt beginnen oder schlimmer werden."
      },
      "pp3": {
        "when": "Innerhalb von 3 Wochen nach der Geburt",
        "title": "Erste Kontrolle",
        "i1": "Sprechen Sie mit Ihrer Hausärztin, Frauenärztin oder Hebamme über Blutung, Schmerzen, Füttern, Stimmung und Schlaf. Ein Telefonat oder Videoanruf kann zählen."
      },
      "ppFull": {
        "when": "Bis 12 Wochen nach der Geburt, oft nach 4–6",
        "title": "Vollständige Nachuntersuchung",
        "i1": "Ein Blick auf die Stimmung, Verhütung, wie Sie heilen, und Pläne für eine nächste Schwangerschaft.",
        "i2": "Wenn Sie Schwangerschaftsdiabetes hatten: ein Zuckertest 4 bis 12 Wochen nach der Geburt. Das Risiko für Typ-2-Diabetes bleibt lebenslang höher, also bitten Sie alle 1 bis 3 Jahre um einen Test.",
        "i3": "Wenn Sie Urin oder Stuhl verlieren, Schmerzen beim Sex haben oder eine Vorwölbung in der Scheide spüren, fragen Sie nach Beckenbodentherapie. Sie hilft. Damit müssen Sie nicht leben."
      }
