        "Zwillinge oder mehr Babys in bestimmten Lagen",
        "Bestimmte Erkrankungen der Mutter (schwere Herzkrankheit, akuter Genitalherpes)",
        "Ungeplante Gründe während der Geburt",
        "Auffälliger Herzschlag des Babys (das Baby zeigt Zeichen von Not)",
        "Geburtsstillstand, kein Fortschritt trotz ausreichender Wehen und Zeit",
        "Plazentaablösung. Die Plazenta löst sich zu früh",
        "Nabelschnurvorfall. Die Nabelschnur kommt vor dem Baby durch den Muttermund",
        "Im Operationssaal",
        "Spinal- oder Periduralanästhesie. Sie sind wach und von der Brust abwärts betäubt",
        "Ein Tuch verdeckt das Operationsfeld. Sie können bitten, es im Moment der Geburt zu senken",
        "Ihre Begleitperson darf meist dabei sein",
        "Sie spüren Druck und Ziehen, keinen Schmerz",
        "Das Baby wird oft auch im OP gleich auf Ihre Brust gelegt („sanfter Kaiserschnitt“)",
        "Gesamtzeit: etwa 45–60 Minuten; die Geburt selbst dauert 5–10 Minuten",
        "Erholung nach dem Kaiserschnitt",
        "Krankenhausaufenthalt: 2–4 Tage (statt 1–2 Tage nach vaginaler Geburt)",
        "Schmerzen werden mit Ibuprofen + Paracetamol nach festem Plan ± kurzzeitig Opioiden behandelt",
        "Aufstehen und Gehen am selben Tag. Sehr wichtig gegen Blutgerinnsel",
        "4–6 Wochen nichts heben, was schwerer ist als Ihr Baby",
        "Der Schnitt ist eine waagerechte Narbe an der „Bikinilinie“, verschlossen mit Klammern oder selbstauflösenden Fäden",
        "Rufen Sie nach der Entlassung an, wenn",
        "Die Wunde aufgeht, die Rötung sich nach außen ausbreitet oder ungewöhnlich nässt · Fieber &gt;{temp:100.4} · Die Schmerzen schlimmer statt besser werden · Sie in einer Stunde 1 Binde durchweichen",
        "VBAC. Vaginale Geburt nach Kaiserschnitt",
        "Wenn Sie einen früheren Kaiserschnitt mit tiefem Querschnitt hatten, ist in dieser Schwangerschaft vielleicht eine VBAC möglich. Sie gelingt in 60–80% der Fälle. Sprechen Sie früh in der Vorsorge darüber."
